import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Character Creation & Backgrounds","description":"","frontmatter":{},"headers":[],"relativePath":"guide/characters/character-creation.md","filePath":"guide/characters/character-creation.md"}'),n={name:"guide/characters/character-creation.md"};function s(o,e,c,d,l,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="character-creation-backgrounds" tabindex="-1">Character Creation &amp; Backgrounds <a class="header-anchor" href="#character-creation-backgrounds" aria-label="Permalink to &quot;Character Creation &amp; Backgrounds&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> These are intended changes, not confirmed live rules. <strong>Implementation/availability:</strong> not established for this redesign. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-08 against the <a href="/Syrolands-Public/game-design/characters/character-creation.html">full design specification</a>.</p><h2 id="a-starting-history-not-a-class" tabindex="-1">A starting history, not a class <a class="header-anchor" href="#a-starting-history-not-a-class" aria-label="Permalink to &quot;A starting history, not a class&quot;">​</a></h2><p>The proposed creation model combines a background, starting competencies and initial knowledge. Your history gives you a useful beginning without fixing your future direction.</p><p>An important starting competency could begin near skill 20 with its fundamentals already known, skipping the initial teacher gate. Exact values and the number of choices are not finalized.</p><h2 id="possible-histories" tabindex="-1">Possible histories <a class="header-anchor" href="#possible-histories" aria-label="Permalink to &quot;Possible histories&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Illustration</th><th>Possible starting direction</th></tr></thead><tbody><tr><td>Hunter&#39;s Apprentice</td><td>Archery, Tracking, Animal Lore and basic field dressing</td></tr><tr><td>Workshop Apprentice</td><td>Carpentry, Tinkering and basic joinery</td></tr><tr><td>Village Healer</td><td>Healing, Anatomy and basic medical knowledge</td></tr></tbody></table><p>These are examples, not confirmed presets. They do not promise starting items, reputation or every technique associated with a skill.</p><h2 id="your-next-steps-remain-open" tabindex="-1">Your next steps remain open <a class="header-anchor" href="#your-next-steps-remain-open" aria-label="Permalink to &quot;Your next steps remain open&quot;">​</a></h2><p>You should be able to pursue other disciplines later through <a href="/Syrolands-Public/guide/characters/skills.html#learning-skills-and-finding-teachers">teachers and practice</a>, and discover <a href="/Syrolands-Public/guide/characters/techniques.html">techniques</a> independently of raw skill. Backgrounds should explain a starting identity without becoming permanent class restrictions.</p><p>Starting stats, exact packages, respec rules and treatment of existing characters remain unresolved. <a href="/Syrolands-Public/guide/characters/stats.html">Stats</a> are being reconsidered so that an early character feels responsive.</p>',11)])])}const g=a(n,[["render",s]]);export{p as __pageData,g as default};
